        return true
      }
      return false
    }
  },
  methods: {
    withGroupCurrency,
    toggleReason (e) {
      e.target.blur() // so the button doesnt remain focused (with black color).
      this.ephemeral.isReasonHidden = !this.ephemeral.isReasonHidden
    }
  }
